def yn(start,texts,page,stance):return {'type':'ynng','sourceInstructions':f'Questions {start} – {start+len(texts)-1} Do the following statements agree with the {stance} of the writer in Reading Passage 3? In boxes {start}-{start+len(texts)-1} on your answer sheet, write YES if the statement agrees with the {stance} of the writer NO if the statement contradicts the {stance} of the writer NOT GIVEN if it is impossible to say what the writer thinks about this','sourcePages':[page],'questions':h.qs(start,texts),'stance':stance}
def drag(start,end,title,texts,bank,page):return {'type':'summary-drag','sourceInstructions':f'Questions {start} – {end} Complete the summary using the list of words, A-{chr(64+len(bank))}, below. Write the correct letter, A-{chr(64+len(bank))}, in boxes {start}-{end} on your answer sheet.','sourcePages':[page],'questions':[{'n':n}for n in range(start,end+1)],'title':title,'content':texts,'bank':[{'value':chr(65+i),'text':t}for i,t in enumerate(bank)],'reuse':False}

